import sys
s = sys.stdin.read().rstrip('\r\n')
stack = []
mapping = {')': '(', '}': '{', ']': '['}
ok = True
for c in s:
    if c in mapping:
        top = stack.pop() if stack else '#'
        if mapping[c] != top: ok = False; break
    else:
        stack.append(c)
print('true' if ok and not stack else 'false')
